    TreeNode<T> parent = node.parent;
    TreeNode<T> left = node.left;
    TreeNode<T> right = node.right;
    TreeNode<T> newParent = right;
    TreeNode<T> newLeft = left.left;
    TreeNode<T> newRight = left.right;
