void write(byte b[]) throws IOException {
    // Process the input byte array in chunks of a specific size
    int chunkSize = 1024;
    int chunks = b.length / chunkSize;
    int remainder = b.length % chunkSize;

    // Write the chunks
    for (int i = 0; i < chunks; i++) {
        write(b, i * chunkSize, chunkSize);
    }

    // Write the remainder
    if (remainder > 0) {
        write(b, chunks * chunkSize, remainder);
    }
}

