void write(final byte[] b, final int off, final int len) throws IOException {
    if (off < 0 || len < 0) {
        throw new IndexOutOfBoundsException();
    }
    if (len == 0) {
        return;
    }
    if (off + len > b.length) {
        throw new IOException("Invalid offset or length");
    }
    for (int i = 0; i < len; i++) {
        int index = off + i;
        if (index >= b.length) {
            break;
        }
        write(b[index]);
    }
}

