public static String capitalize(String name) {
    // Check if the input name is empty or null
    if (name == null || name.isEmpty()) {
        return name;
    }

    // Get the first character of the name
    char firstChar = name.charAt(0);

    // Check if the first character is already capitalized
    if (Character.isUpperCase(firstChar)) {
        return name;
    }

    // Capitalize the first character and return the updated name
    return Character.toUpperCase(firstChar) + name.substring(1);
}

