protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Create a new list to store the edges of the tour
    List<E> tourEdges = new ArrayList<E>();
    for (E edge : tour) {
        tourEdges.add(edge);
    }
    // Create a new list to store the vertices of the tour
    List<V> tourVertices = new ArrayList<V>();
    for (E edge : tourEdges) {
        tourVertices.add(graph.getEdgeSource(edge));
        tourVertices.add(graph.getEdgeTarget(edge));
    }
    // Create a new graph path with the tour edges and vertices
    GraphPath<V,E> path = new GraphPath<V,E>();
    for (int i = 0; i < tourVertices.size(); i++) {
        V vertex = tourVertices.get(i);
        path.addEdge(vertex, tourEdges.get(i), vertex, tourEdges.get(i+1), graph);
    }
    return path;
}
