public static String applyRelativePath(String path, String relativePath) {
    // Handle the trivial cases where the relative path is empty or the same as the full path
    if (relativePath.isEmpty()) {
        return path;
    } else if (relativePath.equals(path)) {
        return path;
    }

    // Parse the relative path and ensure it's well-formed
    List<String> relativePathParts = new ArrayList<>(Arrays.asList(relativePath.split("/")));
    if (relativePathParts.size() == 0 || relativePathParts.get(0).isEmpty()) {
        throw new IllegalArgumentException("Invalid relative path: " + relativePath);
    }

    // Calculate the number of parent directories to move up
    int upCount = 0;
    while (relativePathParts.get(0).equals("..")) {
        upCount++;
        relativePathParts.remove(0);
    }

    // If the relative path doesn't contain any parent directories, return the full path unchanged
    if (upCount == 0) {
        return path;
    }

    // Calculate the full path by starting from the parent directory and appending the remaining relative path
    String fullPath = path.substring(0, path.lastIndexOf('/', path.length() - 1) + 1);
    for (int i = 0; i < upCount; i++) {
        fullPath = fullPath.substring(0, fullPath.lastIndexOf('/', fullPath.length() - 1) + 1);
    }
    for (String part : relativePathParts) {
        fullPath = fullPath + "/" + part;
    }

    return fullPath;
}

